  return isSameDay(day, startDate);
};

isSelectingRangeEnd = () => {
  if (!this.isInSelectingRange()) {
    return false;
  }

  const { day, endDate, selectsEnd, selectsRange, swapRange, startDate } =
    this.props;
  const selectingDate = this.props.selectingDate ?? this.props.preSelection;

